# quatro-backends.tf — os quatro destinos do MESMO vetor, para o benchmark.
# A Knowledge Base do L83 ja existe e continua apontando para o backend A;
# aqui declaramos B, C e D so para a rodada de medicao. Confira a versao do
# provider AWS antes de aplicar: recursos aws_bedrockagent_*, aws_opensearch_*
# e o suporte a S3 Vectors no Knowledge Bases mudaram de shape mais de uma vez.

variable "prefixo" {
  type    = string
  default = "cadencia-l84"
}

# ── Backend B: OpenSearch self-managed, dentro da VPC do L07 ──────────────
resource "aws_opensearch_domain" "backend_b" {
  domain_name    = "${var.prefixo}-opensearch-provisionado"
  engine_version = "OpenSearch_2.15"

  cluster_config {
    instance_type  = "r6g.large.search"
    instance_count = 3
  }

  vpc_options {
    subnet_ids         = [data.aws_subnet.privada_a.id]
    # security group referencia o SG da task do harness, nunca faixa de IP.
    security_group_ids = [aws_security_group.acesso_opensearch.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp3"
    volume_size = 100
  }

  encrypt_at_rest { enabled = true }

  tags = { squad = "atendimento", lab = "L84", finalidade = "benchmark-vetorial" }
}

resource "aws_security_group" "acesso_opensearch" {
  name   = "${var.prefixo}-sg-opensearch"
  vpc_id = data.aws_vpc.cadencia.id

  ingress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    # referencia o SG da task do harness — nunca 0.0.0.0/0 num backend com dado real.
    security_groups = [aws_security_group.harness_benchmark.id]
  }
}

# ── Backend C: S3 Vectors ──────────────────────────────────────────────────
# O recurso nativo do provider AWS para S3 Vectors mudou de nome mais de uma vez
# desde o lancamento do servico; se `aws_s3vectors_index` nao existir na sua
# versao do provider, crie o bucket e o indice via chamada ao SDK (S3VectorsClient)
# num passo de bootstrap, como o harness ja faz para popular o backend.
resource "aws_s3vectors_bucket" "backend_c" {
  bucket = "${var.prefixo}-s3-vectors"
  tags   = { squad = "atendimento", lab = "L84", finalidade = "benchmark-vetorial" }
}

resource "aws_s3vectors_index" "backend_c" {
  bucket_name     = aws_s3vectors_bucket.backend_c.bucket
  index_name      = "cadencia-acervo"
  dimension       = 1024
  distance_metric = "cosine"
}

# ── Backend D: Aurora pgvector — REAPROVEITA o cluster do L14, não cria outro ──
data "aws_rds_cluster" "cadencia" {
  cluster_identifier = "cadencia-pedidos" # o mesmo cluster do L14
}

# A extensão e o índice entram por migração SQL (ver pgvector-indice.sql),
# não por recurso do Terraform — pgvector é extensão do Postgres, não peça de infra.

# ── Log group do harness — cobra por retenção, entra na limpeza ───────────
resource "aws_cloudwatch_log_group" "harness" {
  name              = "/cadencia/l84/harness-benchmark"
  retention_in_days = 30
  tags              = { squad = "atendimento", lab = "L84" }
}

// HarnessPgVector.cs — consulta o backend D (Aurora pgvector) com pool e retry.
// Os outros três backends seguem o mesmo padrão de harness, trocando só o
// cliente de consulta (OpenSearch REST client / S3VectorsClient do SDK).
using Npgsql;
using Polly;
using Polly.Retry;

public sealed class HarnessPgVector
{
    private readonly NpgsqlDataSource _pool;
    private readonly AsyncRetryPolicy _retry;

    public HarnessPgVector(string connectionString)
    {
        // pool, nunca uma conexão nova por requisição — mesma regra do L07/L14.
        _pool = NpgsqlDataSource.Create(connectionString);
        _retry = Policy
            .Handle<NpgsqlException>()
            .WaitAndRetryAsync(3, tentativa =>
                TimeSpan.FromMilliseconds(80 * Math.Pow(2, tentativa))
                + TimeSpan.FromMilliseconds(Random.Shared.Next(0, 40))); // jitter
    }

    public async Task<ResultadoConsulta> ConsultarAsync(float[] vetorConsulta, string chunkIdEsperado)
    {
        var inicio = System.Diagnostics.Stopwatch.StartNew();

        var top5 = await _retry.ExecuteAsync(async () =>
        {
            await using var cmd = _pool.CreateCommand(
                "SELECT chunk_id FROM acervo_vetorial " +
                "ORDER BY embedding <=> $1 LIMIT 5");
            cmd.Parameters.AddWithValue(new Pgvector.Vector(vetorConsulta));

            var ids = new List<string>();
            await using var reader = await cmd.ExecuteReaderAsync();
            while (await reader.ReadAsync())
                ids.Add(reader.GetString(0));
            return ids;
        });

        inicio.Stop();
        return new ResultadoConsulta(
            Backend: "aurora_pgvector",
            Top5ContemEsperado: top5.Contains(chunkIdEsperado),
            LatenciaMs: inicio.ElapsedMilliseconds);
    }
}

public sealed record ResultadoConsulta(string Backend, bool Top5ContemEsperado, long LatenciaMs);
